insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Ancient','statement_based','easy','Consider the following statements about the Bhimbetka rock shelters:','भीमबेटका शैलाश्रयों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["They are in Madhya Pradesh.", "They are a UNESCO World Heritage Site."], "statements_hi": ["ये मध्य प्रदेश में हैं।", "ये UNESCO विश्व धरोहर स्थल हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. The shelters in the Vindhyan hills south of Bhopal, discovered by V.S. Wakankar in 1957, were occupied from the Palaeolithic onwards and carry paintings of animals, hunting and dancing from several periods; they were inscribed as a World Heritage Site in 2003.','दोनों कथन सही हैं। भोपाल के दक्षिण में विंध्य पहाड़ियों के ये शैलाश्रय, जिन्हें 1957 में वी.एस. वाकणकर ने खोजा, पुरापाषाण काल से बसे रहे और इनमें कई कालों के जंतुओं, शिकार और नृत्य के चित्र हैं; इन्हें 2003 में विश्व धरोहर स्थल घोषित किया गया।','ancient-bhimbetka','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 2; UNESCO World Heritage Centre -- Rock Shelters of Bhimbetka.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about Neolithic sites:','नवपाषाण स्थलों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mehrgarh, in present-day Pakistan, has yielded some of the earliest evidence of farming in the subcontinent.", "At Burzahom in Kashmir, people lived in pit dwellings.", "The Neolithic site of Chirand is in Kerala."], "statements_hi": ["वर्तमान पाकिस्तान के मेहरगढ़ से उपमहाद्वीप में खेती के कुछ सबसे पुराने प्रमाण मिले हैं।", "कश्मीर के बुर्ज़होम में लोग गर्त-आवासों (pit dwellings) में रहते थे।", "नवपाषाण स्थल चिरांद केरल में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Mehrgarh, at the foot of the Bolan pass, shows barley and wheat cultivation and domesticated sheep, goats and cattle from about 7000 BCE. At Burzahom people dug pits, entered by steps, as protection from the cold, and sometimes buried dogs with their masters. Statement 3 is wrong: Chirand is on the Ganga in Saran district of Bihar and is known for its bone tools.','कथन 1 और 2 सही हैं। बोलन दर्रे के नीचे मेहरगढ़ में लगभग 7000 ई.पू. से जौ और गेहूँ की खेती और पालतू भेड़, बकरी तथा मवेशी मिलते हैं। बुर्ज़होम में लोगों ने ठंड से बचने के लिए सीढ़ियों वाले गड्ढे खोदे, और कभी-कभी कुत्तों को उनके मालिकों के साथ दफ़नाया। कथन 3 गलत है: चिरांद बिहार के सारण ज़िले में गंगा पर है और अपने अस्थि-उपकरणों के लिए जाना जाता है।','ancient-neolithic-sites','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 3; R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Neolithic.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Excavations at Harappa were begun by Daya Ram Sahni in 1921.", "Mohenjodaro was first excavated by John Marshall."], "statements_hi": ["हड़प्पा में उत्खनन दयाराम साहनी ने 1921 में शुरू किया।", "मोहनजोदड़ो का पहला उत्खनन जॉन मार्शल ने किया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: Mohenjodaro was first excavated by R.D. Banerji in 1922; John Marshall was the Director-General of the Archaeological Survey who announced the discovery of a new civilisation in 1924 and directed the larger excavations that followed -- which is why his name is the trap.','केवल कथन 1 सही है। कथन 2 गलत है: मोहनजोदड़ो का पहला उत्खनन 1922 में आर.डी. बनर्जी ने किया; जॉन मार्शल पुरातत्व सर्वेक्षण के महानिदेशक थे, जिन्होंने 1924 में एक नई सभ्यता की खोज की घोषणा की और बाद के बड़े उत्खननों का निर्देशन किया; इसीलिए उनका नाम जाल है।','ancient-harappa-mohenjodaro-excavation','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Bricks, Beads and Bones; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 4.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about the life of the Buddha:','बुद्ध के जीवन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["He attained enlightenment at Bodh Gaya.", "He belonged to the Shakya clan, whose capital was Kapilavastu.", "He attained mahaparinirvana at Rajagriha."], "statements_hi": ["उन्हें बोधगया में ज्ञान प्राप्त हुआ।", "वे शाक्य कुल के थे, जिसकी राजधानी कपिलवस्तु थी।", "उनका महापरिनिर्वाण राजगृह में हुआ।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Siddhartha, of the Shakya gana of Kapilavastu, attained enlightenment under a pipal tree at Bodh Gaya on the banks of the Niranjana. Statement 3 is wrong: he died at Kushinagar (Kusinara) in the territory of the Mallas; Rajagriha, the Magadhan capital, is where the First Buddhist Council was held soon after -- which is what makes it tempting.','कथन 1 और 2 सही हैं। कपिलवस्तु के शाक्य गण के सिद्धार्थ को निरंजना नदी के किनारे बोधगया में पीपल के पेड़ के नीचे ज्ञान प्राप्त हुआ। कथन 3 गलत है: उनकी मृत्यु मल्लों के क्षेत्र में कुशीनगर (कुसिनारा) में हुई; मगध की राजधानी राजगृह वह स्थान है जहाँ उसके तुरंत बाद पहली बौद्ध संगीति हुई, और यही इसे आकर्षक बनाता है।','ancient-buddha-life-places','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about the Tripitaka:','त्रिपिटक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["It is written in Sanskrit.", "The Vinaya Pitaka contains the rules for the order of monks and nuns."], "statements_hi": ["यह संस्कृत में लिखा गया है।", "विनय पिटक में भिक्षुओं और भिक्षुणियों के संघ के नियम हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. The Tripitaka (''three baskets'') -- the Vinaya Pitaka of monastic rules, the Sutta Pitaka of the Buddha''s discourses and the Abhidhamma Pitaka of philosophical analysis -- was compiled in Pali, the language of the Theravada canon, and written down in Sri Lanka in the first century BCE. Later Mahayana texts were composed in Sanskrit, which is the source of the trap.','केवल कथन 2 सही है। त्रिपिटक (''तीन टोकरियाँ''), यानी संघ के नियमों का विनय पिटक, बुद्ध के उपदेशों का सुत्त पिटक और दार्शनिक विश्लेषण का अभिधम्म पिटक, पालि में संकलित हुआ, जो थेरवाद धर्मग्रंथों की भाषा है, और पहली सदी ई.पू. में श्रीलंका में लिखा गया। बाद के महायान ग्रंथ संस्कृत में रचे गए, और यही जाल का स्रोत है।','ancient-tripitaka','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about Jainism:','जैन धर्म के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ''three jewels'' (triratna) of Jainism are right faith, right knowledge and right conduct.", "Rishabhadeva is regarded as the first Tirthankara.", "Parshvanatha is regarded as the twenty-third Tirthankara."], "statements_hi": ["जैन धर्म के ''त्रिरत्न'' सम्यक् दर्शन (आस्था), सम्यक् ज्ञान और सम्यक् चरित्र हैं।", "ऋषभदेव को पहला तीर्थंकर माना जाता है।", "पार्श्वनाथ को तेईसवाँ तीर्थंकर माना जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Jains hold that liberation comes through the three jewels, and they trace their teaching through 24 Tirthankaras, from Rishabhadeva to Mahavira. Parshvanatha, whom many historians accept as a historical figure of around the 8th century BCE, taught four vows; Mahavira added the fifth, brahmacharya.','तीनों कथन सही हैं। जैन मानते हैं कि मुक्ति त्रिरत्न से मिलती है, और वे अपनी शिक्षा को ऋषभदेव से महावीर तक 24 तीर्थंकरों से जोड़ते हैं। पार्श्वनाथ, जिन्हें कई इतिहासकार लगभग 8वीं सदी ई.पू. का ऐतिहासिक व्यक्ति मानते हैं, ने चार व्रत सिखाए; महावीर ने पाँचवाँ, ब्रह्मचर्य, जोड़ा।','ancient-jain-triratna-tirthankaras','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on Jainism and Buddhism.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Alexander invaded north-western India during the reign of Chandragupta Maurya.", "Porus fought Alexander on the banks of the Ganga."], "statements_hi": ["सिकंदर ने चंद्रगुप्त मौर्य के शासनकाल में उत्तर-पश्चिमी भारत पर आक्रमण किया।", "पोरस ने गंगा के किनारे सिकंदर से युद्ध किया।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": true}]'::jsonb,2,0.66,'Neither statement is correct. Alexander''s invasion (327-325 BCE) came while the Nandas ruled Magadha; Chandragupta Maurya rose to power soon after, partly by driving out the Greek garrisons. Porus fought him at the Hydaspes (Jhelum) in 326 BCE; Alexander''s army refused to go beyond the Beas (Hyphasis), so it never reached the Ganga.','कोई भी कथन सही नहीं है। सिकंदर का आक्रमण (327-325 ई.पू.) तब हुआ जब मगध पर नंदों का शासन था; चंद्रगुप्त मौर्य इसके तुरंत बाद, कुछ हद तक यूनानी सैनिक-टुकड़ियों को भगाकर, सत्ता में आए। पोरस ने 326 ई.पू. में हाइडेस्पीज़ (झेलम) पर उससे युद्ध किया; सिकंदर की सेना ने ब्यास (हाइफ़ेसिस) से आगे जाने से इनकार कर दिया, इसलिए वह कभी गंगा तक नहीं पहुँची।','ancient-alexander-invasion','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on Iranian and Macedonian invasions.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about Sanchi:','साँची के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The core of the Great Stupa was built under Ashoka.", "Its carved gateways (toranas) were made during Ashoka''s own reign.", "Sanchi is in Uttar Pradesh."], "statements_hi": ["महान स्तूप का मूल भाग अशोक के समय बना।", "इसके नक्काशीदार तोरण अशोक के अपने शासनकाल में बनाए गए।", "साँची उत्तर प्रदेश में है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: the brick stupa of Ashoka''s time was enlarged and cased in stone under the Shungas, and the four toranas, carved with Jataka stories and scenes of the Buddha''s life, were added later, in about the first century BCE; one inscription records the ivory-workers of Vidisha as donors. The Begums of Bhopal helped preserve it in the 19th century. Statement 3 is wrong: Sanchi is near Vidisha in Madhya Pradesh.','केवल कथन 1 सही है। कथन 2 गलत है: अशोक के समय के ईंट के स्तूप को शुंगों के समय बड़ा करके पत्थर से ढका गया, और जातक कथाओं तथा बुद्ध के जीवन के दृश्यों से नक्काशीदार चार तोरण बाद में, लगभग पहली सदी ई.पू. में, जोड़े गए; एक अभिलेख विदिशा के हाथीदाँत कारीगरों को दानदाता बताता है। 19वीं सदी में भोपाल की बेगमों ने इसे बचाने में मदद की। कथन 3 गलत है: साँची मध्य प्रदेश में विदिशा के पास है।','ancient-sanchi-stupa','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings (Sanchi); UNESCO -- Buddhist Monuments at Sanchi.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Kalidasa wrote the play ''Abhijnanashakuntalam''.", "Kalidasa wrote the poem ''Meghaduta'', in which a cloud carries a message."], "statements_hi": ["कालिदास ने ''अभिज्ञानशाकुंतलम्'' नाटक लिखा।", "कालिदास ने ''मेघदूत'' काव्य लिखा, जिसमें एक बादल संदेश ले जाता है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Kalidasa, usually placed in the Gupta period, wrote three plays (Abhijnanashakuntalam, Malavikagnimitram, Vikramorvashiyam) and the poems Meghaduta, Raghuvamsha, Kumarasambhava and Ritusamhara. In the Meghaduta an exiled yaksha sends a cloud from central India to his wife in Alaka in the Himalaya.','दोनों कथन सही हैं। सामान्यतः गुप्त काल में रखे जाने वाले कालिदास ने तीन नाटक (अभिज्ञानशाकुंतलम्, मालविकाग्निमित्रम्, विक्रमोर्वशीयम्) और मेघदूत, रघुवंश, कुमारसंभव तथा ऋतुसंहार काव्य लिखे। मेघदूत में एक निर्वासित यक्ष मध्य भारत से हिमालय की अलका में अपनी पत्नी के पास एक बादल भेजता है।','ancient-kalidasa-works','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on literature; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about ancient Indian scholars:','प्राचीन भारतीय विद्वानों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Aryabhata, author of the Aryabhatiya, held that the Earth rotates on its axis.", "The Sushruta Samhita deals mainly with internal medicine rather than surgery.", "Brahmagupta is the author of the Brihat Samhita."], "statements_hi": ["आर्यभटीय के लेखक आर्यभट का मत था कि पृथ्वी अपने अक्ष पर घूमती है।", "सुश्रुत संहिता मुख्य रूप से शल्य-चिकित्सा के बजाय आंतरिक चिकित्सा से संबंधित है।", "ब्रह्मगुप्त बृहत्संहिता के लेखक हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Aryabhata (born 476 CE) explained day and night by the Earth''s rotation and gave a close value of pi. Statement 2 reverses the two classics: the Sushruta Samhita is the great text of surgery, describing operations such as rhinoplasty and cataract couching, while the Charaka Samhita is the classic of internal medicine. Statement 3 is wrong: the Brihat Samhita, an encyclopaedia of astronomy, astrology, architecture and more, is by Varahamihira; Brahmagupta wrote the Brahmasphutasiddhanta, with rules for arithmetic involving zero.','केवल कथन 1 सही है: आर्यभट (जन्म 476 ई.) ने दिन और रात को पृथ्वी के घूर्णन से समझाया और पाई का निकट मान दिया। कथन 2 दोनों ग्रंथों को उलट देता है: सुश्रुत संहिता शल्य-चिकित्सा का महान ग्रंथ है, जिसमें नासिका-संधान (rhinoplasty) और मोतियाबिंद के उपचार जैसी शल्यक्रियाओं का वर्णन है, जबकि चरक संहिता आंतरिक चिकित्सा का प्रमुख ग्रंथ है। कथन 3 गलत है: खगोल, ज्योतिष, वास्तु आदि का विश्वकोश बृहत्संहिता वराहमिहिर की है; ब्रह्मगुप्त ने ब्रह्मस्फुटसिद्धांत लिखा, जिसमें शून्य वाले अंकगणित के नियम हैं।','ancient-scientists-texts','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on science; R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Gupta age.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Panini wrote the Ashtadhyayi, a grammar of Sanskrit.", "Patanjali''s Mahabhashya is a commentary on the Arthashastra."], "statements_hi": ["पाणिनि ने संस्कृत के व्याकरण ग्रंथ अष्टाध्यायी की रचना की।", "पतंजलि का महाभाष्य अर्थशास्त्र पर एक टीका है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Panini, from Gandhara, set out Sanskrit grammar in nearly 4,000 compact rules (sutras), usually dated to the 5th-4th centuries BCE. Statement 2 is wrong: Patanjali''s Mahabhashya (2nd century BCE) is the ''great commentary'' on Panini''s grammar, through Katyayana''s notes on it; it also mentions contemporary events such as a Greek siege of Saketa.','केवल कथन 1 सही है। गांधार के पाणिनि ने संस्कृत व्याकरण को लगभग 4,000 संक्षिप्त नियमों (सूत्रों) में प्रस्तुत किया, जिनका समय सामान्यतः 5वीं-4थी सदी ई.पू. माना जाता है। कथन 2 गलत है: पतंजलि का महाभाष्य (दूसरी सदी ई.पू.) कात्यायन की टिप्पणियों के ज़रिए पाणिनि के व्याकरण पर ''महान टीका'' है; इसमें साकेत पर यूनानी घेरे जैसी समकालीन घटनाओं का उल्लेख भी है।','ancient-panini-patanjali','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 6; A.L. Basham, The Wonder That Was India.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about early Tamil literature:','आरंभिक तमिल साहित्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Manimekalai is a Jain epic.", "The Sangam assemblies of poets are said to have been held at Kanchipuram.", "Silappadikaram is a Buddhist epic."], "statements_hi": ["मणिमेकलै एक जैन महाकाव्य है।", "कहा जाता है कि कवियों की संगम सभाएँ कांचीपुरम में हुई थीं।", "शिलप्पदिकारम एक बौद्ध महाकाव्य है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Manimekalai, by Sattanar, is a Buddhist epic -- the story of Manimekalai, daughter of Kovalan and the dancer Madhavi, who becomes a Buddhist nun. Tamil tradition places the three Sangams at Madurai (and an earlier, legendary one at a lost city), under Pandya patronage. Silappadikaram is not a Buddhist work: its author is traditionally a Jain monk and it reflects Jain ethics. The two epics are linked by story, which is why their religions are easily swapped.','कोई भी कथन सही नहीं है। सात्तनार का मणिमेकलै एक बौद्ध महाकाव्य है, जो कोवलन और नर्तकी माधवी की पुत्री मणिमेकलै की कहानी है, जो बौद्ध भिक्षुणी बनती है। तमिल परंपरा पांड्य संरक्षण में तीनों संगमों को मदुरै में (और एक पुराने, पौराणिक संगम को एक लुप्त नगर में) रखती है। शिलप्पदिकारम बौद्ध रचना नहीं है: परंपरा से इसके लेखक जैन भिक्षु हैं और इसमें जैन नैतिकता झलकती है। दोनों महाकाव्य कथा से जुड़े हैं, इसीलिए इनके धर्म आसानी से आपस में बदल दिए जाते हैं।','ancient-tamil-epics-sangam','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8; NCERT Class VI, Our Pasts I -- Buildings, Paintings and Books.','draft'),
('upsc','History','Ancient','statement_based','easy','Consider the following statements about megaliths in India:','भारत में महापाषाणों (megaliths) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Megalithic burials are found mainly in peninsular India.", "The megalithic cultures of the south are associated with the use of iron."], "statements_hi": ["महापाषाण शवाधान मुख्य रूप से प्रायद्वीपीय भारत में मिलते हैं।", "दक्षिण की महापाषाण संस्कृतियाँ लोहे के उपयोग से जुड़ी हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. Megaliths are graves marked by large stones -- stone circles, cists and dolmens -- found widely in the Deccan and south India from about 1000 BCE; the dead were buried with pots of black-and-red ware, iron tools and weapons, and sometimes horse equipment. Brahmagiri, Adichanallur and Junapani are well-known sites.','दोनों कथन सही हैं। महापाषाण बड़े पत्थरों से चिह्नित कब्रें हैं, जैसे पत्थरों के घेरे, पेटिकाएँ और डोलमेन, जो लगभग 1000 ई.पू. से दक्कन और दक्षिण भारत में व्यापक रूप से मिलते हैं; मृतकों के साथ काले-और-लाल मृद्भांड, लोहे के औज़ार और हथियार, और कभी-कभी घोड़े के साज़ दफ़नाए जाते थे। ब्रह्मगिरि, आदिचनल्लूर और जूनापानी प्रसिद्ध स्थल हैं।','ancient-megaliths-iron','original_pattern_matched','NCERT Class VI, Our Pasts I -- In the Earliest Cities / What Books and Burials Tell Us; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 5.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about Chalcolithic cultures:','ताम्रपाषाण संस्कृतियों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Ahar-Banas culture flourished in south-eastern Rajasthan.", "Inamgaon in Maharashtra was a large settlement of the Jorwe culture.", "The Chalcolithic people of the Deccan buried their dead in cemeteries far away from their houses."], "statements_hi": ["आहाड़-बनास संस्कृति दक्षिण-पूर्वी राजस्थान में फली-फूली।", "महाराष्ट्र का इनामगाँव जोर्वे संस्कृति की एक बड़ी बस्ती था।", "दक्कन के ताम्रपाषाण लोग अपने मृतकों को घरों से बहुत दूर कब्रिस्तानों में दफ़नाते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Ahar, near Udaipur, smelted copper from local ores; Inamgaon, on the Ghod river, was a large Jorwe settlement with a chief''s house, a granary and an irrigation channel. Statement 3 is wrong: in Maharashtra the dead were usually buried under the floors of the houses, with pots and copper objects, often in a north-south position -- a sign of beliefs about the dead living among the family.','कथन 1 और 2 सही हैं। उदयपुर के पास आहाड़ में स्थानीय अयस्कों से ताँबा गलाया जाता था; घोड नदी पर इनामगाँव एक बड़ी जोर्वे बस्ती थी, जिसमें मुखिया का घर, अन्नभंडार और एक सिंचाई नहर थी। कथन 3 गलत है: महाराष्ट्र में मृतकों को प्रायः घरों के फ़र्श के नीचे बर्तनों और ताँबे की वस्तुओं के साथ, अक्सर उत्तर-दक्षिण स्थिति में, दफ़नाया जाता था; यह इस विश्वास का संकेत है कि मृतक परिवार के बीच ही रहते हैं।','ancient-chalcolithic-cultures','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on Chalcolithic farming cultures; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 5.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Harappan civilisation:','हड़प्पा सभ्यता के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Harappans were among the earliest people in the world to grow cotton.", "The horse is commonly shown on Harappan seals.", "The houses in Harappan cities usually opened directly onto the main streets."], "statements_hi": ["हड़प्पावासी विश्व में कपास उगाने वाले सबसे पहले लोगों में थे।", "हड़प्पाई मुहरों पर घोड़ा आम तौर पर दिखाया गया है।", "हड़प्पाई नगरों के घर सामान्यतः सीधे मुख्य सड़कों पर खुलते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: cotton fragments at Mohenjodaro and cotton seeds at Mehrgarh are among the earliest evidence of the crop, which the Greeks later called ''sindon''. Statement 2 is wrong: the humped bull, the ''unicorn'', the elephant, the tiger and the rhinoceros appear on seals, but the horse is almost entirely absent -- a point in the debate on the Harappans'' relation to the Vedic people. Statement 3 is wrong: houses were usually entered from side lanes, with no windows on the main streets, which kept the busy roads separate from domestic life.','केवल कथन 1 सही है: मोहनजोदड़ो में कपास के टुकड़े और मेहरगढ़ में कपास के बीज इस फ़सल के सबसे पुराने प्रमाणों में हैं, जिसे बाद में यूनानियों ने ''सिंडन'' कहा। कथन 2 गलत है: मुहरों पर कूबड़ वाला बैल, ''एकशृंगी'', हाथी, बाघ और गैंडा दिखते हैं, पर घोड़ा लगभग पूरी तरह अनुपस्थित है; यह हड़प्पावासियों और वैदिक लोगों के संबंध की बहस का एक बिंदु है। कथन 3 गलत है: घरों में प्रायः बगल की गलियों से प्रवेश होता था और मुख्य सड़कों पर खिड़कियाँ नहीं होती थीं, जिससे व्यस्त सड़कें घरेलू जीवन से अलग रहती थीं।','ancient-harappan-cotton-horse-houses','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Bricks, Beads and Bones; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 4.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Rig Vedic period:','ऋग्वैदिक काल के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The ''Battle of the Ten Kings'' was fought on the banks of the Parushni (Ravi).", "Indra is the deity to whom the largest number of hymns in the Rig Veda are addressed.", "Rig Vedic society depended mainly on settled agriculture, and cattle were of little importance."], "statements_hi": ["''दस राजाओं का युद्ध'' (दाशराज्ञ युद्ध) परुष्णी (रावी) के किनारे लड़ा गया।", "ऋग्वेद में सबसे अधिक सूक्त इंद्र को समर्पित हैं।", "ऋग्वैदिक समाज मुख्यतः स्थायी खेती पर निर्भर था, और मवेशियों का महत्त्व कम था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Bharata chief Sudasa defeated a confederacy of ten tribes on the Parushni, as the seventh mandala records. Indra, the warrior god who breaks forts and releases the waters, receives about 250 hymns; Agni comes next. Statement 3 is wrong: Rig Vedic society was largely pastoral. Wealth was counted in cattle, a wealthy man was ''gomat'', a war was ''gavishti'' (the search for cows), and cows are among the most frequently mentioned things in the text; agriculture grew in importance only in the later Vedic period.','कथन 1 और 2 सही हैं। भरत कबीले के सरदार सुदास ने परुष्णी पर दस कबीलों के संघ को हराया, जैसा सातवाँ मंडल बताता है। दुर्गों को तोड़ने और जल को मुक्त करने वाले योद्धा देवता इंद्र को लगभग 250 सूक्त मिलते हैं; अग्नि दूसरे स्थान पर हैं। कथन 3 गलत है: ऋग्वैदिक समाज मुख्यतः पशुपालक था। संपत्ति मवेशियों में गिनी जाती थी, धनी व्यक्ति ''गोमत'' था, युद्ध ''गविष्टि'' (गायों की खोज) था, और गायें ग्रंथ में सबसे अधिक उल्लिखित चीज़ों में हैं; खेती का महत्त्व उत्तर वैदिक काल में ही बढ़ा।','ancient-rig-vedic-society','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Rig Vedic age; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 5.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Upanishads are also known as the Vedanta, the ''end of the Veda''.", "There are six Vedangas, the auxiliary disciplines for the study of the Vedas.", "The Upanishads discuss the relation between atman and brahman."], "statements_hi": ["उपनिषदों को वेदांत, यानी ''वेद का अंत'', भी कहा जाता है।", "वेदांग छह हैं, जो वेदों के अध्ययन के सहायक विषय हैं।", "उपनिषद आत्मा और ब्रह्म के संबंध पर विचार करते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The Upanishads come at the end of the Vedic corpus and turn from ritual to philosophy -- above all to the idea that the individual self (atman) is one with the universal reality (brahman) -- which is why they are called Vedanta. The six Vedangas cover phonetics, ritual, grammar, etymology, metre and astronomy, and helped preserve the Vedas accurately.','तीनों कथन सही हैं। उपनिषद वैदिक साहित्य के अंत में आते हैं और कर्मकांड से दर्शन की ओर मुड़ते हैं, सबसे बढ़कर इस विचार की ओर कि व्यक्तिगत आत्मा (आत्मन्) सार्वभौम सत्य (ब्रह्म) से एक है; इसीलिए इन्हें वेदांत कहा जाता है। छह वेदांग ध्वनि-विज्ञान, कर्मकांड, व्याकरण, निरुक्त, छंद और ज्योतिष को शामिल करते हैं, और इन्होंने वेदों को सटीक रूप से बचाए रखने में मदद की।','ancient-upanishads-vedangas','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 5; A.L. Basham, The Wonder That Was India, chapter on religion.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about Magadha before the Mauryas:','मौर्यों से पहले के मगध के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Bimbisara of the Haryanka dynasty strengthened Magadha through marriage alliances.", "Ajatashatru was a contemporary of Ashoka.", "According to Greek accounts, the Nandas had only a small army."], "statements_hi": ["हर्यंक वंश के बिंबिसार ने वैवाहिक संबंधों के ज़रिए मगध को मज़बूत किया।", "अजातशत्रु अशोक का समकालीन था।", "यूनानी विवरणों के अनुसार नंदों के पास केवल छोटी सेना थी।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Bimbisara married princesses of Kosala, Vaishali (the Lichchhavis) and the Madra clan, which brought him territory and prestige; he also annexed Anga. Statement 2 is wrong: Ajatashatru was a contemporary of the Buddha and Mahavira, about two centuries before Ashoka; he fought the Vajji confederacy using new war engines. Statement 3 is wrong: Greek writers report that the Nanda king had a huge force of infantry, cavalry, chariots and war elephants, and fear of it was one reason Alexander''s soldiers refused to go beyond the Beas.','केवल कथन 1 सही है: बिंबिसार ने कोसल, वैशाली (लिच्छवि) और मद्र कुल की राजकुमारियों से विवाह किए, जिनसे उन्हें क्षेत्र और प्रतिष्ठा मिली; उन्होंने अंग को भी मिला लिया। कथन 2 गलत है: अजातशत्रु बुद्ध और महावीर का समकालीन था, अशोक से लगभग दो सदी पहले; उसने नए युद्ध-यंत्रों से वज्जि संघ से युद्ध किया। कथन 3 गलत है: यूनानी लेखक बताते हैं कि नंद राजा के पास पैदल सैनिकों, घुड़सवारों, रथों और युद्ध-हाथियों की विशाल सेना थी, और उसका डर एक कारण था कि सिकंदर के सैनिकों ने ब्यास से आगे जाने से इनकार किया।','ancient-magadha-haryanka-nanda','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on territorial states and the rise of Magadha.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Indo-Greeks and their contacts:','हिंद-यवनों (Indo-Greeks) और उनके संपर्कों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The dialogue between Menander and the monk Nagasena is recorded in a Jain text.", "The Heliodorus pillar at Besnagar was set up by an envoy of a Kushana king.", "Indo-Greek coins carried no written legends."], "statements_hi": ["मिनांडर और भिक्षु नागसेन के संवाद एक जैन ग्रंथ में दर्ज हैं।", "बेसनगर का हेलियोडोरस स्तंभ एक कुषाण राजा के दूत ने स्थापित किया।", "हिंद-यवन सिक्कों पर कोई लिखित लेख नहीं होते थे।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The Milindapanha (''Questions of Milinda''), in which Menander questions Nagasena, is a Buddhist Pali text. The Garuda pillar at Besnagar near Vidisha was set up by Heliodorus, envoy of the Indo-Greek king Antialcidas of Taxila, who called himself a ''Bhagavata'', a devotee of Vasudeva -- early evidence of a Greek adopting an Indian faith. Indo-Greek coins are known for their realistic royal portraits and bilingual legends, in Greek on one side and Prakrit in Kharoshthi on the other; for many rulers they are the only record that survives.','कोई भी कथन सही नहीं है। मिलिंदपन्ह (''मिलिंद के प्रश्न''), जिसमें मिनांडर नागसेन से प्रश्न पूछते हैं, एक बौद्ध पालि ग्रंथ है। विदिशा के पास बेसनगर का गरुड़ स्तंभ तक्षशिला के हिंद-यवन राजा एंटियालकिडस के दूत हेलियोडोरस ने स्थापित किया, जिसने स्वयं को वासुदेव का भक्त ''भागवत'' कहा; यह किसी यूनानी के भारतीय आस्था अपनाने का आरंभिक प्रमाण है। हिंद-यवन सिक्के अपने यथार्थवादी राजकीय चित्रों और द्विभाषी लेखों के लिए प्रसिद्ध हैं, एक ओर यूनानी में और दूसरी ओर खरोष्ठी में प्राकृत; कई शासकों का यही एकमात्र बचा हुआ प्रमाण है।','ancient-indo-greeks-contacts','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on Central Asian contacts; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Kushanas:','कुषाणों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Kushanas issued gold coins on a large scale.", "The Kushanas were of Greek origin.", "At its height, the Kushana empire extended from Central Asia to the Gangetic plain."], "statements_hi": ["कुषाणों ने बड़े पैमाने पर सोने के सिक्के चलाए।", "कुषाण यूनानी मूल के थे।", "अपने चरम पर कुषाण साम्राज्य मध्य एशिया से गंगा के मैदान तक फैला था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The Kushanas minted plentiful gold coins, drawing on Roman gold that came through trade, and their coins show Greek, Iranian and Indian deities; their empire ran from the Oxus region through Gandhara and Mathura to Varanasi, as an inscription at Sarnath shows. Statement 2 is wrong: the Kushanas were a branch of the Yuezhi, a people from the steppes of north-western China who moved into Bactria; they used the Greek script for their own language, Bactrian, which may explain the confusion.','कथन 1 और 3 सही हैं। कुषाणों ने व्यापार से आए रोमन सोने के सहारे प्रचुर मात्रा में सोने के सिक्के ढाले, और उनके सिक्कों पर यूनानी, ईरानी और भारतीय देवता दिखते हैं; उनका साम्राज्य वक्षु (Oxus) क्षेत्र से गांधार और मथुरा होते हुए वाराणसी तक था, जैसा सारनाथ का एक अभिलेख दिखाता है। कथन 2 गलत है: कुषाण यूएझी की एक शाखा थे, जो उत्तर-पश्चिमी चीन के घास के मैदानों के लोग थे और बैक्ट्रिया में आ बसे; वे अपनी भाषा, बैक्ट्रियन, के लिए यूनानी लिपि का उपयोग करते थे, जिससे यह भ्रम पैदा हो सकता है।','ancient-kushanas-empire-coins','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Kushanas; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Gupta rulers:','गुप्त शासकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Gupta era is reckoned from 319-20 CE, taken to be the accession of Chandragupta I.", "Skandagupta resisted invasions by the Hunas.", "The Mehrauli iron pillar has resisted rusting for more than 1,500 years."], "statements_hi": ["गुप्त संवत् 319-20 ई. से गिना जाता है, जिसे चंद्रगुप्त प्रथम का राज्यारोहण माना जाता है।", "स्कंदगुप्त ने हूणों के आक्रमणों का प्रतिरोध किया।", "महरौली का लौह स्तंभ 1,500 से अधिक वर्षों से जंग से बचा हुआ है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Chandragupta I, who took the title Maharajadhiraja, is generally credited with founding the Gupta era. Skandagupta''s Bhitari pillar inscription describes his wars against the Hunas, which strained the empire''s resources. The Mehrauli pillar, about 7 m tall and inscribed in the name of a king ''Chandra'', owes its resistance to corrosion to the high phosphorus content of the wrought iron and the thin protective film that formed on it -- evidence of Gupta-age metallurgy.','तीनों कथन सही हैं। महाराजाधिराज की उपाधि लेने वाले चंद्रगुप्त प्रथम को सामान्यतः गुप्त संवत् शुरू करने का श्रेय दिया जाता है। स्कंदगुप्त का भितरी स्तंभ अभिलेख हूणों के विरुद्ध उसके युद्धों का वर्णन करता है, जिन्होंने साम्राज्य के संसाधनों पर दबाव डाला। लगभग 7 मीटर ऊँचा और ''चंद्र'' नाम के राजा के नाम पर अभिलेखित महरौली स्तंभ जंग-प्रतिरोध के लिए पिटवाँ लोहे में फ़ॉस्फ़ोरस की अधिक मात्रा और उस पर बनी पतली सुरक्षात्मक परत का ऋणी है; यह गुप्तकालीन धातु-विज्ञान का प्रमाण है।','ancient-gupta-rulers-iron-pillar','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Guptas; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 9.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about Gupta-period temples and caves:','गुप्तकालीन मंदिरों और गुफाओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Dashavatara temple at Deogarh is a rock-cut cave temple.", "The temple at Bhitargaon is built of stone.", "The Udayagiri caves near Vidisha are Buddhist caves."], "statements_hi": ["देवगढ़ का दशावतार मंदिर एक शैलकृत गुफा-मंदिर है।", "भीतरगाँव का मंदिर पत्थर से बना है।", "विदिशा के पास उदयगिरि की गुफाएँ बौद्ध गुफाएँ हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. The Dashavatara temple at Deogarh (Lalitpur district, Uttar Pradesh) is a free-standing structural stone temple, among the earliest to have a shikhara, with panels such as Vishnu reclining on the serpent. The Bhitargaon temple near Kanpur is one of the oldest surviving brick temples, decorated with terracotta panels. The Udayagiri caves are mostly Hindu (with one Jain cave), and their great Varaha panel, showing Vishnu as a boar rescuing the earth, is dated to the reign of Chandragupta II.','कोई भी कथन सही नहीं है। देवगढ़ (उत्तर प्रदेश का ललितपुर ज़िला) का दशावतार मंदिर स्वतंत्र रूप से बना संरचनात्मक पत्थर का मंदिर है, शिखर वाले सबसे पुराने मंदिरों में से एक, जिसमें शेषशायी विष्णु जैसे फलक हैं। कानपुर के पास भीतरगाँव का मंदिर बचे हुए सबसे पुराने ईंट के मंदिरों में से एक है, जो टेराकोटा फलकों से सजा है। उदयगिरि की गुफाएँ अधिकतर हिंदू हैं (एक जैन गुफा के साथ), और पृथ्वी को बचाते वराह रूप विष्णु का इनका महान फलक चंद्रगुप्त द्वितीय के शासनकाल का माना जाता है।','ancient-gupta-temples-caves','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 9; NCERT Class XI, An Introduction to Indian Art -- Temple Architecture and Sculpture.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Chalukyas of Badami:','बादामी के चालुक्यों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Aihole inscription of Pulakeshin II was composed by the poet Ravikirti.", "Their capital was Vatapi (Badami).", "They were finally overthrown by the Cholas."], "statements_hi": ["पुलकेशिन द्वितीय का ऐहोल अभिलेख कवि रविकीर्ति ने रचा।", "उनकी राजधानी वातापी (बादामी) थी।", "अंततः उन्हें चोलों ने उखाड़ फेंका।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Ravikirti''s Sanskrit prashasti at Aihole (634 CE) praises Pulakeshin II''s victories, and the Chalukyas built famous temples at Aihole, Badami and Pattadakal. Statement 3 is wrong: after long wars with the Pallavas -- Narasimhavarman I even captured Vatapi and took the title ''Vatapikonda'' -- the Badami Chalukyas were overthrown by their feudatory Dantidurga, founder of the Rashtrakuta dynasty, around 753 CE. The Cholas rose to power more than a century later.','कथन 1 और 2 सही हैं। ऐहोल में रविकीर्ति की संस्कृत प्रशस्ति (634 ई.) पुलकेशिन द्वितीय की विजयों की प्रशंसा करती है, और चालुक्यों ने ऐहोल, बादामी और पट्टडकल में प्रसिद्ध मंदिर बनाए। कथन 3 गलत है: पल्लवों से लंबे युद्धों के बाद, जिनमें नरसिंहवर्मन प्रथम ने वातापी पर कब्ज़ा करके ''वातापीकोंड'' की उपाधि भी ली, बादामी के चालुक्यों को लगभग 753 ई. में उनके सामंत दंतिदुर्ग ने उखाड़ फेंका, जिसने राष्ट्रकूट वंश की स्थापना की। चोल सौ वर्ष से अधिक बाद सत्ता में आए।','ancient-badami-chalukyas','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 10; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about heterodox schools of thought:','अवैदिक (heterodox) विचार-धाराओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Makkhali Gosala was a leading teacher of the Ajivikas.", "The Barabar caves were dedicated by Ashoka to Jain monks.", "The Charvaka (Lokayata) school accepted the authority of the Vedas."], "statements_hi": ["मक्खलि गोसाल आजीविकों के प्रमुख आचार्य थे।", "बराबर की गुफाएँ अशोक ने जैन भिक्षुओं को समर्पित कीं।", "चार्वाक (लोकायत) दर्शन वेदों की प्रामाणिकता स्वीकार करता था।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: Makkhali Gosala, once a companion of Mahavira, taught niyati, a strict fatalism in which human effort could not change one''s destiny. Statement 2 is wrong: Ashoka and his grandson Dasharatha dedicated the rock-cut Barabar and Nagarjuni caves near Gaya to the Ajivikas; the Lomas Rishi cave there has the earliest carved doorway imitating a wooden hut. Statement 3 is wrong: the Charvakas were materialists who accepted only perception as a source of knowledge and rejected the Vedas, ritual and the idea of an afterlife.','केवल कथन 1 सही है: कभी महावीर के साथी रहे मक्खलि गोसाल ने नियति, यानी ऐसे कठोर भाग्यवाद की शिक्षा दी जिसमें मनुष्य का प्रयास भाग्य नहीं बदल सकता। कथन 2 गलत है: अशोक और उनके पौत्र दशरथ ने गया के पास शैलकृत बराबर और नागार्जुनी गुफाएँ आजीविकों को समर्पित कीं; वहाँ की लोमस ऋषि गुफा में लकड़ी की झोपड़ी की नकल करता सबसे पुराना तराशा हुआ प्रवेश-द्वार है। कथन 3 गलत है: चार्वाक भौतिकवादी थे, जो केवल प्रत्यक्ष को ज्ञान का स्रोत मानते थे और वेदों, कर्मकांड और परलोक के विचार को अस्वीकार करते थे।','ancient-ajivikas-charvaka','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 6.','draft'),
('upsc','History','Ancient','statement_based','medium','Consider the following statements about the Satavahanas:','सातवाहनों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Several Satavahana kings were known by their mothers'' names, such as Gautamiputra.", "The Satavahanas were among the earliest rulers to make land grants to Brahmanas and Buddhist monks.", "The Satavahanas issued coins of lead and potin."], "statements_hi": ["कई सातवाहन राजा अपनी माताओं के नामों से जाने जाते थे, जैसे गौतमीपुत्र।", "सातवाहन ब्राह्मणों और बौद्ध भिक्षुओं को भूमि-दान देने वाले सबसे आरंभिक शासकों में थे।", "सातवाहनों ने सीसे और पोटिन के सिक्के चलाए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Names such as Gautamiputra and Vasishthiputra point to the importance of the mother''s lineage, though the succession passed through the male line. Their inscriptions record some of the earliest grants of land, with exemptions from royal interference, to Brahmanas and to Buddhist monks, as in the caves at Nashik and Karle. Besides silver and copper, they issued a great many coins of lead and potin (an alloy), many bearing ships -- a sign of their sea trade.','तीनों कथन सही हैं। गौतमीपुत्र और वासिष्ठीपुत्र जैसे नाम माँ के वंश के महत्त्व की ओर संकेत करते हैं, हालाँकि उत्तराधिकार पुरुष-वंश से चलता था। उनके अभिलेख ब्राह्मणों और बौद्ध भिक्षुओं को राजकीय हस्तक्षेप से छूट के साथ दिए गए सबसे आरंभिक भूमि-दानों में से कुछ को दर्ज करते हैं, जैसे नासिक और कार्ले की गुफाओं में। चाँदी और ताँबे के अलावा उन्होंने सीसे और पोटिन (एक मिश्र धातु) के बहुत से सिक्के चलाए, जिनमें से कई पर जहाज़ बने हैं; यह उनके समुद्री व्यापार का संकेत है।','ancient-satavahanas-matronymics-grants','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Satavahanas; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about the location of Harappan sites:','हड़प्पाई स्थलों की अवस्थिति के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Harappa lies on the Ravi.", "Mohenjodaro lies on the Indus.", "Ropar lies on the Beas.", "Banawali lies on the Chambal."], "statements_hi": ["हड़प्पा रावी पर स्थित है।", "मोहनजोदड़ो सिंधु पर स्थित है।", "रोपड़ ब्यास पर स्थित है।", "बनावली चंबल पर स्थित है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": false}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Harappa lies on the Ravi in Punjab (Pakistan) and Mohenjodaro on the Indus in Sindh. Ropar (Rupnagar) is on the Sutlej in Indian Punjab, where it leaves the Shivaliks; Banawali, in Fatehabad district of Haryana, lies in the dry bed of the Ghaggar-Hakra (the old Saraswati) system, not on the Chambal, which the Harappans hardly reached. Knowing the rivers helps place the Harappan heartland between the Indus and the Ghaggar.','कथन 1 और 2 सही हैं। हड़प्पा पंजाब (पाकिस्तान) में रावी पर और मोहनजोदड़ो सिंध में सिंधु पर स्थित है। रोपड़ (रूपनगर) भारतीय पंजाब में सतलुज पर वहाँ है जहाँ वह शिवालिक से निकलती है; हरियाणा के फ़तेहाबाद ज़िले का बनावली घग्गर-हाकरा (पुरानी सरस्वती) प्रणाली के सूखे तल पर है, चंबल पर नहीं, जहाँ तक हड़प्पावासी शायद ही पहुँचे। नदियाँ जानने से हड़प्पाई केंद्र-भूमि को सिंधु और घग्गर के बीच रखने में मदद मिलती है।','ancient-harappan-sites-rivers','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 4 (map of Harappan sites); NCERT Class XII, Themes in Indian History I -- Bricks, Beads and Bones.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about Buddhist schools:','बौद्ध संप्रदायों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mahayana Buddhism worshipped the Buddha in image form and developed the ideal of the Bodhisattva.", "The canonical texts of the Theravada school are in Sanskrit.", "Vajrayana Buddhism developed first in Sri Lanka."], "statements_hi": ["महायान बौद्ध धर्म ने बुद्ध की मूर्ति-रूप में पूजा की और बोधिसत्व का आदर्श विकसित किया।", "थेरवाद संप्रदाय के धर्मग्रंथ संस्कृत में हैं।", "वज्रयान बौद्ध धर्म सबसे पहले श्रीलंका में विकसित हुआ।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: in Mahayana, the Buddha became an object of devotion shown in images (as in Gandhara and Mathura art), and Bodhisattvas -- beings who delay their own liberation to help others -- became central. Statement 2 is wrong: the Theravada canon, followed in Sri Lanka, Myanmar and Thailand, is in Pali. Statement 3 is wrong: Vajrayana, with its mantras, mandalas and rituals, developed in eastern India, at centres such as Vikramashila, and spread to Tibet; Sri Lanka remained Theravada.','केवल कथन 1 सही है: महायान में बुद्ध मूर्तियों में दिखाए जाने वाले भक्ति के पात्र बने (जैसे गांधार और मथुरा कला में), और बोधिसत्व, यानी दूसरों की सहायता के लिए अपनी मुक्ति टालने वाले, केंद्रीय बन गए। कथन 2 गलत है: श्रीलंका, म्यांमार और थाईलैंड में माना जाने वाला थेरवाद धर्मग्रंथ पालि में है। कथन 3 गलत है: मंत्रों, मंडलों और अनुष्ठानों वाला वज्रयान पूर्वी भारत में, विक्रमशिला जैसे केंद्रों में, विकसित हुआ और तिब्बत में फैला; श्रीलंका थेरवादी ही रहा।','ancient-buddhist-schools','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings; Upinder Singh, A History of Ancient and Early Medieval India (Pearson).','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about Jain philosophy:','जैन दर्शन के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["''Anekantavada'' holds that reality has many aspects and cannot be grasped fully from a single point of view.", "''Syadvada'' expresses judgements in a sevenfold form, each qualified by ''syat'' (''in some respect'').", "Jainism does not believe in a creator god."], "statements_hi": ["''अनेकांतवाद'' मानता है कि सत्य के अनेक पक्ष हैं और उसे किसी एक दृष्टिकोण से पूरी तरह नहीं समझा जा सकता।", "''स्याद्वाद'' निर्णयों को सात रूपों में व्यक्त करता है, जिनमें हर एक ''स्यात्'' (''किसी अर्थ में'') से सीमित होता है।", "जैन धर्म किसी सृष्टिकर्ता ईश्वर में विश्वास नहीं करता।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The idea of many-sidedness (anekantavada), often illustrated by the story of the blind men and the elephant, is expressed through the sevenfold predication of syadvada, which qualifies every statement. Jainism holds that the universe is eternal and uncreated, and that souls reach liberation by their own effort, not through the grace of a god.','तीनों कथन सही हैं। अनेक पक्षों (अनेकांतवाद) का विचार, जिसे प्रायः अंधों और हाथी की कथा से समझाया जाता है, स्याद्वाद के सात प्रकार के कथन-रूपों से व्यक्त होता है, जो हर कथन को सीमित करता है। जैन धर्म मानता है कि ब्रह्मांड शाश्वत और असृष्ट है, और आत्माएँ किसी ईश्वर की कृपा से नहीं, अपने प्रयास से मुक्ति पाती हैं।','ancient-jain-philosophy','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on religion; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about inscriptions:','अभिलेखों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Eran inscription of 510 CE is regarded as the earliest epigraphic evidence of the practice of sati.", "The Maski edict refers to the emperor by the name ''Ashoka''.", "The Rabatak inscription, which gives a genealogy of the Kushana kings, is written in the Bactrian language.", "The Nanaghat inscription belongs to the Mauryas."], "statements_hi": ["510 ई. के एरण अभिलेख को सती प्रथा का सबसे पुराना अभिलेखीय प्रमाण माना जाता है।", "मास्की अभिलेख सम्राट को ''अशोक'' नाम से संबोधित करता है।", "कुषाण राजाओं की वंशावली देने वाला रबातक अभिलेख बैक्ट्रियन भाषा में लिखा गया है।", "नानाघाट अभिलेख मौर्यों का है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. The Eran pillar inscription records that the wife of Goparaja, who fell in battle, followed him onto the pyre. Most edicts call the emperor ''Devanampiya Piyadasi''; the Maski edict in Karnataka (found in 1915) was the first found to name him Ashoka, which settled the identification. The Rabatak inscription from Afghanistan, in Bactrian written in Greek script, lists Kanishka''s ancestors. Statement 4 is wrong: the Nanaghat inscription near Pune was issued by the Satavahana queen Naganika and records Vedic sacrifices and gifts.','कथन 1, 2 और 3 सही हैं। एरण स्तंभ अभिलेख बताता है कि युद्ध में मारे गए गोपराज की पत्नी उसके साथ चिता पर चढ़ गई। अधिकांश अभिलेख सम्राट को ''देवानांपिय पियदसि'' कहते हैं; कर्नाटक का मास्की अभिलेख (1915 में मिला) उन्हें अशोक नाम देने वाला पहला मिला अभिलेख था, जिससे पहचान तय हुई। अफ़ग़ानिस्तान का रबातक अभिलेख, जो यूनानी लिपि में बैक्ट्रियन भाषा में है, कनिष्क के पूर्वजों को गिनाता है। कथन 4 गलत है: पुणे के पास का नानाघाट अभिलेख सातवाहन रानी नागनिका ने जारी किया और इसमें वैदिक यज्ञों और दानों का उल्लेख है।','ancient-inscriptions-eran-maski-rabatak','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson) (epigraphic sources); R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about literature of the Gupta period:','गुप्त काल के साहित्य के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["In Kalidasa''s plays, the king and high-caste men speak Sanskrit, while women and characters of lower rank speak Prakrit.", "The Amarakosha, a Sanskrit lexicon, was compiled by Amarasimha.", "The Panchatantra was composed by Banabhatta."], "statements_hi": ["कालिदास के नाटकों में राजा और उच्च वर्ण के पुरुष संस्कृत बोलते हैं, जबकि स्त्रियाँ और निम्न स्तर के पात्र प्राकृत बोलते हैं।", "संस्कृत शब्दकोश अमरकोश अमरसिंह ने संकलित किया।", "पंचतंत्र की रचना बाणभट्ट ने की।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The use of language in Sanskrit drama mirrors social hierarchy: Sanskrit for kings, Brahmanas and men of rank, Prakrit for women and servants -- a clue historians use when reading these plays as sources. The Amarakosha arranges Sanskrit words by subject and was memorised by generations of students. Statement 3 is wrong: the Panchatantra, animal fables teaching statecraft to princes, is attributed to Vishnu Sharma; Banabhatta, who lived later at Harsha''s court, wrote the Harshacharita and Kadambari.','कथन 1 और 2 सही हैं। संस्कृत नाटक में भाषा का उपयोग सामाजिक पदानुक्रम को दिखाता है: राजाओं, ब्राह्मणों और प्रतिष्ठित पुरुषों के लिए संस्कृत, स्त्रियों और सेवकों के लिए प्राकृत; इतिहासकार इन नाटकों को स्रोत के रूप में पढ़ते समय इसी सुराग का उपयोग करते हैं। अमरकोश संस्कृत शब्दों को विषय के अनुसार सजाता है और पीढ़ियों के विद्यार्थियों ने इसे कंठस्थ किया। कथन 3 गलत है: राजकुमारों को राजनीति सिखाने वाली पशु-कथाओं वाला पंचतंत्र विष्णु शर्मा को माना जाता है; बाद में हर्ष के दरबार में रहे बाणभट्ट ने हर्षचरित और कादंबरी लिखीं।','ancient-gupta-literature','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Gupta age; A.L. Basham, The Wonder That Was India, chapter on literature.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about Mauryan art:','मौर्य कला के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Mauryan pillars are monolithic shafts of sandstone, many of it from Chunar.", "The Didarganj Yakshi was found at Sanchi.", "Mauryan pillars were built in sections joined together, like Persian columns."], "statements_hi": ["मौर्य स्तंभ बलुआ पत्थर के एकाश्म (monolithic) स्तंभ हैं, जिनमें से कई का पत्थर चुनार से आया।", "दीदारगंज यक्षी साँची में मिली थी।", "मौर्य स्तंभ फ़ारसी स्तंभों की तरह अलग-अलग खंडों को जोड़कर बनाए गए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Each shaft was cut from a single block of fine-grained sandstone, often from Chunar near Varanasi, and given a mirror-like polish; the animal capitals were carved separately. Statement 2 is wrong: the Didarganj Yakshi, a life-size woman holding a chauri with the same polish, was found in 1917 at Didarganj on the Ganga near Patna, the Mauryan capital, though some scholars date it a little later. Statement 3 is wrong and marks a key difference: Achaemenid Persian columns were built up in segments and stood on bases as parts of buildings, whereas Mauryan pillars are free-standing monoliths without a base -- one reason historians debate how much Persian influence there was.','केवल कथन 1 सही है। हर स्तंभ महीन कणों वाले बलुआ पत्थर के एक ही खंड से काटा गया, जो प्रायः वाराणसी के पास चुनार से आता था, और उस पर दर्पण जैसी पॉलिश की गई; पशु-शीर्ष अलग से तराशे गए। कथन 2 गलत है: वही पॉलिश लिए चँवरधारी आदमकद स्त्री दीदारगंज यक्षी 1917 में मौर्य राजधानी पटना के पास गंगा किनारे दीदारगंज में मिली थी, हालाँकि कुछ विद्वान इसे थोड़ा बाद का मानते हैं। कथन 3 गलत है और एक मुख्य अंतर दिखाता है: हख़ामनी फ़ारसी स्तंभ खंडों को जोड़कर बनाए जाते थे और इमारतों के भाग के रूप में आधारों पर खड़े होते थे, जबकि मौर्य स्तंभ बिना आधार के स्वतंत्र एकाश्म हैं; यह एक कारण है कि इतिहासकार फ़ारसी प्रभाव की मात्रा पर बहस करते हैं।','ancient-mauryan-art-pillars','original_pattern_matched','NCERT Class XI, An Introduction to Indian Art -- Arts of the Mauryan Period; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 7.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements about pottery traditions and coins:','मृद्भांड परंपराओं और सिक्कों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Northern Black Polished Ware is associated with the Harappan cities.", "Punch-marked coins were first issued by the Kushanas.", "Painted Grey Ware is found mainly in the Harappan cities of Sindh."], "statements_hi": ["उत्तरी काली पॉलिश वाले मृद्भांड (NBPW) हड़प्पाई नगरों से जुड़े हैं।", "आहत (punch-marked) सिक्के सबसे पहले कुषाणों ने जारी किए।", "चित्रित धूसर मृद्भांड (PGW) मुख्य रूप से सिंध के हड़प्पाई नगरों में मिलते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. Northern Black Polished Ware, a glossy, fine pottery, marks the ''second urbanisation'' of the Ganga valley in the age of the Mahajanapadas and the Mauryas, from about the 6th century BCE. Punch-marked coins of silver and copper, stamped with symbols, appear in the same period, centuries before the Kushanas. Painted Grey Ware is found in the Ganga-Yamuna doab and the upper Ganga plain and is linked with the later Vedic settlements, such as Hastinapur and Ahichchhatra, not with the Harappans. Getting the sequence of wares right is how archaeologists date sites.','कोई भी कथन सही नहीं है। चमकदार, महीन उत्तरी काली पॉलिश वाले मृद्भांड लगभग छठी सदी ई.पू. से महाजनपदों और मौर्यों के युग में गंगा घाटी के ''दूसरे नगरीकरण'' के चिह्न हैं। चिह्नों से मुद्रांकित चाँदी और ताँबे के आहत सिक्के उसी काल में, कुषाणों से सदियों पहले, दिखाई देते हैं। चित्रित धूसर मृद्भांड गंगा-यमुना दोआब और ऊपरी गंगा मैदान में मिलते हैं और हस्तिनापुर तथा अहिच्छत्र जैसी उत्तर वैदिक बस्तियों से जुड़े हैं, हड़प्पावासियों से नहीं। मृद्भांडों का सही क्रम जानना ही वह तरीका है जिससे पुरातत्वविद स्थलों का काल तय करते हैं।','ancient-nbpw-pgw-punch-marked','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapters 5 and 6; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','mcq','medium','The Buddhist philosopher Nagarjuna is associated above all with:','बौद्ध दार्शनिक नागार्जुन मुख्य रूप से किससे जुड़े हैं?','{}'::jsonb,'[{"id": "a", "body": "Vijnanavada, the ''consciousness-only'' school", "body_hi": "विज्ञानवाद, ''केवल चेतना'' वाला संप्रदाय", "isCorrect": false}, {"id": "b", "body": "The Theravada Abhidhamma", "body_hi": "थेरवाद अभिधम्म", "isCorrect": false}, {"id": "c", "body": "The Madhyamaka (Shunyavada) school", "body_hi": "माध्यमिक (शून्यवाद) संप्रदाय", "isCorrect": true}, {"id": "d", "body": "Vajrayana tantric ritual", "body_hi": "वज्रयान तांत्रिक अनुष्ठान", "isCorrect": false}]'::jsonb,2,0.66,'Nagarjuna (about 2nd century CE) founded the Madhyamaka (''middle way'') school of Mahayana philosophy, which argued that all things are empty (shunya) of independent existence. Vijnanavada (Yogachara), the closest distractor, was developed later by Asanga and Vasubandhu and held that only consciousness is real. The Nagarjunakonda site in Andhra Pradesh is named after him by tradition.','नागार्जुन (लगभग दूसरी सदी ई.) ने महायान दर्शन के माध्यमिक (''मध्यम मार्ग'') संप्रदाय की स्थापना की, जिसने तर्क दिया कि सभी वस्तुएँ स्वतंत्र अस्तित्व से शून्य हैं। सबसे निकट का गलत विकल्प विज्ञानवाद (योगाचार) बाद में असंग और वसुबंधु ने विकसित किया, और वह मानता था कि केवल चेतना ही वास्तविक है। आंध्र प्रदेश के नागार्जुनकोंडा स्थल का नाम परंपरा से उन्हीं पर है।','ancient-nagarjuna-madhyamaka','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on religion; Upinder Singh, A History of Ancient and Early Medieval India (Pearson).','draft'),
('upsc','History','Ancient','mcq','medium','The ''Buddhacharita'', a Sanskrit poem on the life of the Buddha, was written by:','बुद्ध के जीवन पर संस्कृत काव्य ''बुद्धचरित'' किसने लिखा?','{}'::jsonb,'[{"id": "a", "body": "Ashvaghosha", "body_hi": "अश्वघोष", "isCorrect": true}, {"id": "b", "body": "Nagarjuna", "body_hi": "नागार्जुन", "isCorrect": false}, {"id": "c", "body": "Vasubandhu", "body_hi": "वसुबंधु", "isCorrect": false}, {"id": "d", "body": "Buddhaghosa", "body_hi": "बुद्धघोष", "isCorrect": false}]'::jsonb,2,0.66,'Ashvaghosha, a poet and Buddhist teacher traditionally linked with Kanishka''s court, wrote the Buddhacharita and the Saundarananda, among the earliest Sanskrit kavyas. Buddhaghosa, the tempting similar name, was a 5th-century commentator on the Pali canon in Sri Lanka, while Nagarjuna and Vasubandhu were philosophers.','कवि और बौद्ध आचार्य अश्वघोष, जिन्हें परंपरा से कनिष्क के दरबार से जोड़ा जाता है, ने बुद्धचरित और सौंदरनंद लिखे, जो सबसे आरंभिक संस्कृत काव्यों में हैं। मिलता-जुलता नाम बुद्धघोष 5वीं सदी में श्रीलंका में पालि धर्मग्रंथों के टीकाकार थे, जबकि नागार्जुन और वसुबंधु दार्शनिक थे।','ancient-ashvaghosha-buddhacharita','original_pattern_matched','A.L. Basham, The Wonder That Was India; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','mcq','medium','The Nanda dynasty of Magadha was founded by:','मगध के नंद वंश की स्थापना किसने की?','{}'::jsonb,'[{"id": "a", "body": "Dhana Nanda", "body_hi": "धनानंद", "isCorrect": false}, {"id": "b", "body": "Shishunaga", "body_hi": "शिशुनाग", "isCorrect": false}, {"id": "c", "body": "Udayin (Udayabhadra)", "body_hi": "उदयिन (उदयभद्र)", "isCorrect": false}, {"id": "d", "body": "Mahapadma Nanda", "body_hi": "महापद्म नंद", "isCorrect": true}]'::jsonb,2,0.66,'Mahapadma Nanda, described in the Puranas as a destroyer of Kshatriyas and of low birth, founded the dynasty and expanded Magadha, perhaps as far as Kalinga, where the Hathigumpha inscription speaks of a Nanda king''s canal. Dhana Nanda was the last Nanda king, overthrown by Chandragupta Maurya; Shishunaga founded the preceding dynasty; and Udayin, a Haryanka king, moved the capital to Pataliputra.','पुराणों में क्षत्रियों का नाश करने वाले और निम्न कुल के बताए गए महापद्म नंद ने वंश की स्थापना की और मगध का विस्तार किया, संभवतः कलिंग तक, जहाँ हाथीगुम्फा अभिलेख एक नंद राजा की नहर की बात करता है। धनानंद अंतिम नंद राजा थे, जिन्हें चंद्रगुप्त मौर्य ने हटाया; शिशुनाग ने पिछले वंश की स्थापना की; और हर्यंक राजा उदयिन ने राजधानी पाटलिपुत्र स्थानांतरित की।','ancient-mahapadma-nanda','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the rise of Magadha.','draft'),
('upsc','History','Ancient','mcq','medium','The Mehrauli iron pillar inscription names the king who set it up as:','महरौली लौह स्तंभ अभिलेख उसे स्थापित करने वाले राजा का नाम क्या बताता है?','{}'::jsonb,'[{"id": "a", "body": "Skanda", "body_hi": "स्कंद", "isCorrect": false}, {"id": "b", "body": "Chandra", "body_hi": "चंद्र", "isCorrect": true}, {"id": "c", "body": "Kumara", "body_hi": "कुमार", "isCorrect": false}, {"id": "d", "body": "Samudra", "body_hi": "समुद्र", "isCorrect": false}]'::jsonb,2,0.66,'The Sanskrit inscription praises a king called only ''Chandra'', who conquered the Vangas and crossed the ''seven mouths of the Indus'', and set up the pillar as a standard of Vishnu; most historians identify him with Chandragupta II. Its original site is thought to have been Udayagiri near Vidisha; it was later brought to Delhi. The distractors are the short forms of other Gupta names.','संस्कृत अभिलेख केवल ''चंद्र'' नाम के राजा की प्रशंसा करता है, जिसने वंगों को जीता और ''सिंधु के सात मुहानों'' को पार किया, और स्तंभ को विष्णु के ध्वज के रूप में स्थापित किया; अधिकांश इतिहासकार उसे चंद्रगुप्त द्वितीय मानते हैं। माना जाता है कि इसका मूल स्थान विदिशा के पास उदयगिरि था; बाद में इसे दिल्ली लाया गया। गलत विकल्प दूसरे गुप्त नामों के छोटे रूप हैं।','ancient-mehrauli-pillar-chandra','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 9; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','mcq','medium','The Chinese pilgrim who studied at Nalanda in the late seventh century and wrote an account of Buddhist monastic practice in India was:','सातवीं सदी के उत्तरार्ध में नालंदा में अध्ययन करने वाला और भारत में बौद्ध मठीय आचरण का विवरण लिखने वाला चीनी तीर्थयात्री कौन था?','{}'::jsonb,'[{"id": "a", "body": "Fa-hien (Faxian)", "body_hi": "फ़ाह्यान (फ़ाशियान)", "isCorrect": false}, {"id": "b", "body": "Hiuen Tsang (Xuanzang)", "body_hi": "ह्वेनसांग (श्वेनज़ांग)", "isCorrect": false}, {"id": "c", "body": "I-tsing (Yijing)", "body_hi": "इत्सिंग (यिजिंग)", "isCorrect": true}, {"id": "d", "body": "Sung Yun", "body_hi": "सुंग युन", "isCorrect": false}]'::jsonb,2,0.66,'I-tsing reached India by sea about 673 CE, spent about ten years at Nalanda and wrote ''A Record of the Buddhist Religion as Practised in India'', describing monastic rules and daily life. Fa-hien came in the early 5th century and Hiuen Tsang in the 7th, under Harsha; Sung Yun visited the north-west in the early 6th century.','इत्सिंग लगभग 673 ई. में समुद्र मार्ग से भारत पहुँचा, लगभग दस वर्ष नालंदा में रहा और ''भारत में आचरित बौद्ध धर्म का विवरण'' लिखा, जिसमें मठीय नियमों और दैनिक जीवन का वर्णन है। फ़ाह्यान 5वीं सदी के आरंभ में और ह्वेनसांग 7वीं सदी में हर्ष के समय आया; सुंग युन 6ठी सदी के आरंभ में उत्तर-पश्चिम आया।','ancient-i-tsing-nalanda','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 10; R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','mcq','easy','In Jainism, the word ''Tirthankara'' means:','जैन धर्म में ''तीर्थंकर'' शब्द का अर्थ है:','{}'::jsonb,'[{"id": "a", "body": "A ''ford-maker'' who shows the way across the stream of rebirth", "body_hi": "''घाट बनाने वाला'', जो पुनर्जन्म की धारा के पार जाने का मार्ग दिखाता है", "isCorrect": true}, {"id": "b", "body": "A lay follower who has taken the twelve minor vows of householders", "body_hi": "गृहस्थों के बारह लघु व्रत लेने वाला उपासक", "isCorrect": false}, {"id": "c", "body": "A king who protects the faith", "body_hi": "धर्म की रक्षा करने वाला राजा", "isCorrect": false}, {"id": "d", "body": "A teacher of Vedic ritual", "body_hi": "वैदिक कर्मकांड का आचार्य", "isCorrect": false}]'::jsonb,2,0.66,'A Tirthankara is literally a ''maker of a ford'' (tirtha) -- a liberated teacher who has crossed the river of rebirth and shows others how to cross it. Mahavira was the 24th and last of this age. Lay Jains (shravakas) take the minor vows (anuvratas), while monks take the great vows (mahavratas).','तीर्थंकर का शाब्दिक अर्थ है ''घाट (तीर्थ) बनाने वाला'', यानी वह मुक्त आचार्य जिसने पुनर्जन्म की नदी पार कर ली है और दूसरों को उसे पार करने का मार्ग दिखाता है। महावीर इस युग के 24वें और अंतिम तीर्थंकर थे। जैन उपासक (श्रावक) अणुव्रत लेते हैं, जबकि भिक्षु महाव्रत लेते हैं।','ancient-tirthankara-meaning','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on Jainism.','draft'),
('upsc','History','Ancient','mcq','easy','The ''Sapta Sindhu'', the land of seven rivers, is associated with:','''सप्त सिंधु'', यानी सात नदियों की भूमि, किससे जुड़ी है?','{}'::jsonb,'[{"id": "a", "body": "The Harappans of Sindh", "body_hi": "सिंध के हड़प्पावासी", "isCorrect": false}, {"id": "b", "body": "The Mauryas", "body_hi": "मौर्य", "isCorrect": false}, {"id": "c", "body": "The Kushanas", "body_hi": "कुषाण", "isCorrect": false}, {"id": "d", "body": "The Rig Vedic people", "body_hi": "ऋग्वैदिक लोग", "isCorrect": true}]'::jsonb,2,0.66,'The Rig Veda describes the land of the early Vedic people as Sapta Sindhu, watered by the Indus, its tributaries in Punjab and the Saraswati; the Ganga is mentioned only once or twice, showing that their world lay in the north-west. The Harappans lived in much the same region, which is why they are the trap, but the name comes from Vedic texts.','ऋग्वेद आरंभिक वैदिक लोगों की भूमि को सप्त सिंधु बताता है, जिसे सिंधु, पंजाब में उसकी सहायक नदियाँ और सरस्वती सींचती थीं; गंगा का उल्लेख केवल एक-दो बार है, जिससे पता चलता है कि उनकी दुनिया उत्तर-पश्चिम में थी। हड़प्पावासी भी लगभग इसी क्षेत्र में रहते थे, इसीलिए वे जाल हैं, पर यह नाम वैदिक ग्रंथों से आता है।','ancient-sapta-sindhu','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapter on the Rig Vedic age.','draft'),
('upsc','History','Ancient','mcq','easy','Taxila (Takshashila), a famous centre of learning, was the capital of which region?','शिक्षा का प्रसिद्ध केंद्र तक्षशिला किस क्षेत्र की राजधानी थी?','{}'::jsonb,'[{"id": "a", "body": "Magadha", "body_hi": "मगध", "isCorrect": false}, {"id": "b", "body": "Gandhara", "body_hi": "गांधार", "isCorrect": true}, {"id": "c", "body": "Avanti", "body_hi": "अवंति", "isCorrect": false}, {"id": "d", "body": "Panchala", "body_hi": "पंचाल", "isCorrect": false}]'::jsonb,2,0.66,'Taxila, near present-day Islamabad, was the capital of Gandhara, one of the sixteen Mahajanapadas; it lay on the route between India, Iran and Central Asia and was ruled in turn by the Achaemenids, the Mauryas, the Indo-Greeks, the Shakas and the Kushanas. Tradition links Chanakya and the physician Jivaka with its teachers.','वर्तमान इस्लामाबाद के पास तक्षशिला गांधार की राजधानी थी, जो सोलह महाजनपदों में से एक था; यह भारत, ईरान और मध्य एशिया के बीच के मार्ग पर थी और क्रमशः हख़ामनी, मौर्य, हिंद-यवन, शक और कुषाण यहाँ शासन करते रहे। परंपरा चाणक्य और वैद्य जीवक को इसके आचार्यों से जोड़ती है।','ancient-taxila-gandhara','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press); Upinder Singh, A History of Ancient and Early Medieval India (Pearson).','draft'),
('upsc','History','Ancient','mcq','easy','The Dhamek Stupa stands at:','धमेख स्तूप कहाँ स्थित है?','{}'::jsonb,'[{"id": "a", "body": "Sanchi", "body_hi": "साँची", "isCorrect": false}, {"id": "b", "body": "Bharhut", "body_hi": "भरहुत", "isCorrect": false}, {"id": "c", "body": "Sarnath", "body_hi": "सारनाथ", "isCorrect": true}, {"id": "d", "body": "Amaravati", "body_hi": "अमरावती", "isCorrect": false}]'::jsonb,2,0.66,'The Dhamek Stupa at Sarnath, near Varanasi, marks by tradition the spot where the Buddha gave his first sermon; the present structure dates largely from the Gupta period, with fine carved floral bands. Sanchi, Bharhut and Amaravati are other great stupa sites.','वाराणसी के पास सारनाथ का धमेख स्तूप परंपरा से उस स्थान को चिह्नित करता है जहाँ बुद्ध ने अपना पहला उपदेश दिया; वर्तमान संरचना मुख्यतः गुप्त काल की है, जिसमें सुंदर तराशी हुई पुष्प-पट्टियाँ हैं। साँची, भरहुत और अमरावती दूसरे महान स्तूप-स्थल हैं।','ancient-dhamek-stupa-sarnath','original_pattern_matched','Archaeological Survey of India -- Sarnath; NCERT Class XII, Themes in Indian History I.','draft'),
('upsc','History','Ancient','mcq','easy','The Jataka tales describe:','जातक कथाएँ किसका वर्णन करती हैं?','{}'::jsonb,'[{"id": "a", "body": "Previous births of the Buddha", "body_hi": "बुद्ध के पूर्व जन्मों का", "isCorrect": true}, {"id": "b", "body": "Rules for monks and nuns", "body_hi": "भिक्षुओं और भिक्षुणियों के नियमों का", "isCorrect": false}, {"id": "c", "body": "The lives of the Tirthankaras", "body_hi": "तीर्थंकरों के जीवन का", "isCorrect": false}, {"id": "d", "body": "The Buddhist councils", "body_hi": "बौद्ध संगीतियों का", "isCorrect": false}]'::jsonb,2,0.66,'The Jatakas, part of the Sutta Pitaka, are stories of the Buddha''s earlier lives as the Bodhisattva, often as an animal, each teaching a virtue; they were carved on the railings and gateways of Bharhut and Sanchi and are also a source on the social and economic life of the time. Monastic rules are in the Vinaya Pitaka.','सुत्त पिटक का भाग जातक बोधिसत्व के रूप में, प्रायः किसी पशु के रूप में, बुद्ध के पहले के जीवनों की कथाएँ हैं, जिनमें हर एक कोई गुण सिखाती है; ये भरहुत और साँची की वेदिकाओं और तोरणों पर उकेरी गईं और उस समय के सामाजिक और आर्थिक जीवन का भी स्रोत हैं। संघ के नियम विनय पिटक में हैं।','ancient-jataka-tales','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Thinkers, Beliefs and Buildings.','draft'),
('upsc','History','Ancient','mcq','easy','The Brahmi script of the Ashokan inscriptions was deciphered in 1837 by:','अशोक के अभिलेखों की ब्राह्मी लिपि को 1837 में किसने पढ़ा?','{}'::jsonb,'[{"id": "a", "body": "Alexander Cunningham", "body_hi": "अलेक्ज़ेंडर कनिंघम", "isCorrect": false}, {"id": "b", "body": "William Jones", "body_hi": "विलियम जोन्स", "isCorrect": false}, {"id": "c", "body": "John Marshall", "body_hi": "जॉन मार्शल", "isCorrect": false}, {"id": "d", "body": "James Prinsep", "body_hi": "जेम्स प्रिंसेप", "isCorrect": true}]'::jsonb,2,0.66,'James Prinsep, an official of the Calcutta mint and secretary of the Asiatic Society, deciphered Brahmi (and soon after Kharoshthi), which made it possible to read Ashoka''s edicts and opened up the history of the Mauryas. Cunningham founded the Archaeological Survey, Jones founded the Asiatic Society, and Marshall directed the Harappan excavations.','कलकत्ता टकसाल के अधिकारी और एशियाटिक सोसाइटी के सचिव जेम्स प्रिंसेप ने ब्राह्मी (और उसके तुरंत बाद खरोष्ठी) पढ़ी, जिससे अशोक के अभिलेख पढ़ना संभव हुआ और मौर्यों का इतिहास खुला। कनिंघम ने पुरातत्व सर्वेक्षण की स्थापना की, जोन्स ने एशियाटिक सोसाइटी की, और मार्शल ने हड़प्पाई उत्खननों का निर्देशन किया।','ancient-prinsep-brahmi','original_pattern_matched','NCERT Class XII, Themes in Indian History I -- Kings, Farmers and Towns.','draft'),
('upsc','History','Ancient','mcq','easy','Which one of the following is a Vedanga?','निम्नलिखित में से कौन-सा एक वेदांग है?','{}'::jsonb,'[{"id": "a", "body": "Ayurveda", "body_hi": "आयुर्वेद", "isCorrect": false}, {"id": "b", "body": "Jyotisha", "body_hi": "ज्योतिष", "isCorrect": true}, {"id": "c", "body": "Dhanurveda", "body_hi": "धनुर्वेद", "isCorrect": false}, {"id": "d", "body": "Gandharvaveda", "body_hi": "गंधर्ववेद", "isCorrect": false}]'::jsonb,2,0.66,'Jyotisha, the study of astronomy for fixing the times of sacrifices, is one of the six Vedangas. Ayurveda (medicine), Dhanurveda (archery and warfare) and Gandharvaveda (music) are Upavedas, ''subsidiary Vedas'' of applied knowledge -- the similar ''-veda'' endings are the trap.','यज्ञों का समय तय करने के लिए खगोल का अध्ययन ज्योतिष छह वेदांगों में से एक है। आयुर्वेद (चिकित्सा), धनुर्वेद (धनुर्विद्या और युद्ध) और गंधर्ववेद (संगीत) उपवेद हैं, यानी व्यावहारिक ज्ञान के ''सहायक वेद''; मिलते-जुलते ''-वेद'' अंत ही जाल हैं।','ancient-vedanga-jyotisha','original_pattern_matched','A.L. Basham, The Wonder That Was India; Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 5.','draft'),
('upsc','History','Ancient','mcq','easy','Which Tamil work is often called the ''Tamil Veda''?','किस तमिल रचना को प्रायः ''तमिल वेद'' कहा जाता है?','{}'::jsonb,'[{"id": "a", "body": "Tolkappiyam", "body_hi": "तोल्काप्पियम", "isCorrect": false}, {"id": "b", "body": "Manimekalai", "body_hi": "मणिमेकलै", "isCorrect": false}, {"id": "c", "body": "Tirukkural", "body_hi": "तिरुक्कुरल", "isCorrect": true}, {"id": "d", "body": "Jivaka Chintamani", "body_hi": "जीवक चिंतामणि", "isCorrect": false}]'::jsonb,2,0.66,'The Tirukkural of Tiruvalluvar, 1,330 couplets on virtue (aram), wealth (porul) and love (inbam), is revered across communities as a universal ethical guide and is called the ''Tamil Veda''. The Tolkappiyam is a grammar, and Manimekalai and Jivaka Chintamani are epics.','तिरुवल्लुवर का तिरुक्कुरल, यानी धर्म (अरम्), अर्थ (पोरुल) और काम (इन्बम्) पर 1,330 दोहे, सभी समुदायों में सार्वभौम नैतिक मार्गदर्शक के रूप में पूजनीय है और इसे ''तमिल वेद'' कहा जाता है। तोल्काप्पियम एक व्याकरण है, और मणिमेकलै तथा जीवक चिंतामणि महाकाव्य हैं।','ancient-tirukkural-tamil-veda','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8.','draft'),
('upsc','History','Ancient','mcq','hard','Arrange the following dynasties of Magadha and north India in chronological order:','मगध और उत्तर भारत के निम्नलिखित राजवंशों को कालक्रम में व्यवस्थित कीजिए:','{"statements": ["Haryanka", "Shunga", "Nanda", "Maurya"], "statements_hi": ["हर्यंक", "शुंग", "नंद", "मौर्य"], "closing": "Select the correct order using the code given below:", "closing_hi": "नीचे दिए गए कूट का प्रयोग कर सही क्रम चुनिए:"}'::jsonb,'[{"id": "a", "body": "1-3-4-2", "body_hi": "1-3-4-2", "isCorrect": true}, {"id": "b", "body": "3-1-4-2", "body_hi": "3-1-4-2", "isCorrect": false}, {"id": "c", "body": "1-3-2-4", "body_hi": "1-3-2-4", "isCorrect": false}, {"id": "d", "body": "3-1-2-4", "body_hi": "3-1-2-4", "isCorrect": false}]'::jsonb,2,0.66,'The order is Haryanka (Bimbisara and Ajatashatru, 6th-5th centuries BCE), then -- after the Shishunagas -- the Nandas (4th century BCE), the Mauryas (from about 321 BCE) and the Shungas (from about 185 BCE). The distractors test two common confusions: placing the Nandas before the Haryankas, and placing the Shungas before the Mauryas.','क्रम है: हर्यंक (बिंबिसार और अजातशत्रु, 6ठी-5वीं सदी ई.पू.), फिर, शिशुनागों के बाद, नंद (4थी सदी ई.पू.), मौर्य (लगभग 321 ई.पू. से) और शुंग (लगभग 185 ई.पू. से)। गलत विकल्प दो आम भ्रमों को परखते हैं: नंदों को हर्यंकों से पहले रखना, और शुंगों को मौर्यों से पहले रखना।','ancient-magadha-dynasties-chronology','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapters on Magadha and the Mauryas.','draft'),
('upsc','History','Ancient','mcq','hard','The ''Sulba Sutras'' are an important source for the history of:','''शुल्ब सूत्र'' किसके इतिहास के महत्त्वपूर्ण स्रोत हैं?','{}'::jsonb,'[{"id": "a", "body": "Geometry, through rules for building fire altars", "body_hi": "यज्ञ-वेदियाँ बनाने के नियमों के ज़रिए ज्यामिति", "isCorrect": true}, {"id": "b", "body": "Astronomy, through tables for computing the motion of the planets", "body_hi": "ग्रहों की गति की गणना की सारणियों के ज़रिए खगोल", "isCorrect": false}, {"id": "c", "body": "Medicine, through descriptions of surgery", "body_hi": "शल्य-क्रिया के वर्णनों के ज़रिए चिकित्सा", "isCorrect": false}, {"id": "d", "body": "Grammar, through rules of Sanskrit", "body_hi": "संस्कृत के नियमों के ज़रिए व्याकरण", "isCorrect": false}]'::jsonb,2,0.66,'The Sulba (''cord'') Sutras, part of the Kalpa Sutras, give rules for measuring and constructing Vedic fire altars of exact shapes and areas; in doing so they state what is now called the Pythagorean theorem and give approximations of the square root of two. Baudhayana''s is the oldest. They show that early Indian geometry grew out of ritual needs.','कल्प सूत्रों का भाग शुल्ब (''रस्सी'') सूत्र सटीक आकार और क्षेत्रफल की वैदिक यज्ञ-वेदियाँ मापने और बनाने के नियम देते हैं; ऐसा करते हुए वे वह प्रमेय बताते हैं जिसे आज पाइथागोरस प्रमेय कहा जाता है, और दो के वर्गमूल के निकट मान देते हैं। बौधायन का शुल्ब सूत्र सबसे पुराना है। ये दिखाते हैं कि आरंभिक भारतीय ज्यामिति कर्मकांड की ज़रूरतों से विकसित हुई।','ancient-sulba-sutras-geometry','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on science; Upinder Singh, A History of Ancient and Early Medieval India (Pearson).','draft'),
('upsc','History','Ancient','mcq','hard','The Ikshvakus, known for their patronage of Buddhism at Nagarjunakonda, ruled in:','नागार्जुनकोंडा में बौद्ध धर्म के संरक्षण के लिए प्रसिद्ध इक्ष्वाकुओं ने कहाँ शासन किया?','{}'::jsonb,'[{"id": "a", "body": "The Kaveri delta", "body_hi": "कावेरी डेल्टा", "isCorrect": false}, {"id": "b", "body": "The upper Narmada valley in central India", "body_hi": "मध्य भारत में ऊपरी नर्मदा घाटी", "isCorrect": false}, {"id": "c", "body": "Kalinga", "body_hi": "कलिंग", "isCorrect": false}, {"id": "d", "body": "The lower Krishna valley in Andhra", "body_hi": "आंध्र में निचली कृष्णा घाटी", "isCorrect": true}]'::jsonb,2,0.66,'After the Satavahanas, the Ikshvakus ruled the lower Krishna valley from Vijayapuri (Nagarjunakonda) in the 3rd-4th centuries CE; while the kings performed Vedic sacrifices, their queens and princesses built great Buddhist monasteries and stupas. The site was submerged by the Nagarjuna Sagar dam, and its monuments were moved to a hilltop island.','सातवाहनों के बाद तीसरी-चौथी सदी ई. में इक्ष्वाकुओं ने विजयपुरी (नागार्जुनकोंडा) से निचली कृष्णा घाटी पर शासन किया; जहाँ राजा वैदिक यज्ञ करते थे, वहीं उनकी रानियों और राजकुमारियों ने बड़े बौद्ध विहार और स्तूप बनवाए। नागार्जुन सागर बाँध से यह स्थल डूब गया, और इसके स्मारक एक पहाड़ी टापू पर ले जाए गए।','ancient-ikshvakus-nagarjunakonda','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 8; Archaeological Survey of India -- Nagarjunakonda.','draft'),
('upsc','History','Ancient','match_the_following','medium','Consider the following pairs of schools of Indian philosophy and the thinkers traditionally regarded as their founders:','भारतीय दर्शन के संप्रदायों और परंपरा से उनके संस्थापक माने जाने वाले विचारकों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Nyaya", "2. Vaisheshika", "3. Sankhya", "4. Mimamsa"], "list_1_hi": ["1. न्याय", "2. वैशेषिक", "3. सांख्य", "4. मीमांसा"], "list_2": ["Gautama", "Kanada", "Patanjali", "Jaimini"], "list_2_hi": ["गौतम", "कणाद", "पतंजलि", "जैमिनि"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. The six orthodox (astika) darshanas are Nyaya (logic, Gautama), Vaisheshika (atomism, Kanada), Sankhya (Kapila), Yoga (Patanjali), Mimamsa (ritual interpretation, Jaimini) and Vedanta (Badarayana). Pair 3 is wrong: Sankhya is attributed to Kapila; Patanjali is linked with Yoga, which accepts Sankhya''s framework -- which is why the two are easily swapped.','तीन युग्म सही हैं। छह आस्तिक दर्शन हैं: न्याय (तर्क, गौतम), वैशेषिक (परमाणुवाद, कणाद), सांख्य (कपिल), योग (पतंजलि), मीमांसा (कर्मकांड की व्याख्या, जैमिनि) और वेदांत (बादरायण)। युग्म 3 गलत है: सांख्य कपिल का माना जाता है; पतंजलि योग से जुड़े हैं, जो सांख्य का ढाँचा स्वीकार करता है; इसीलिए दोनों आसानी से आपस में बदल दिए जाते हैं।','ancient-darshanas-founders-pairs','original_pattern_matched','A.L. Basham, The Wonder That Was India, chapter on religion and philosophy.','draft'),
('upsc','History','Ancient','match_the_following','medium','Consider the following pairs of texts and the religious traditions to which they belong:','ग्रंथों और जिन धार्मिक परंपराओं से वे संबंधित हैं, उनके निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Acharanga Sutra", "2. Dipavamsa", "3. Brihadaranyaka", "4. Kalpa Sutra of Bhadrabahu"], "list_1_hi": ["1. आचारांग सूत्र", "2. दीपवंश", "3. बृहदारण्यक", "4. भद्रबाहु का कल्पसूत्र"], "list_2": ["Jainism", "Buddhism", "Buddhism", "Buddhism"], "list_2_hi": ["जैन धर्म", "बौद्ध धर्म", "बौद्ध धर्म", "बौद्ध धर्म"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 2 are correct. The Acharanga is the first of the twelve Jain Angas, on the conduct of monks, and the Dipavamsa is a Pali chronicle of Sri Lanka''s Buddhist history, a source for Ashoka''s missions. Pair 3 is wrong: the Brihadaranyaka is one of the oldest Upanishads. Pair 4 is wrong: the Kalpa Sutra attributed to Bhadrabahu is a Jain text containing the lives of the Tirthankaras -- not to be confused with the Vedic Kalpa Sutras on ritual.','केवल युग्म 1 और 2 सही हैं। आचारांग बारह जैन अंगों में पहला है, जो भिक्षुओं के आचरण पर है, और दीपवंश श्रीलंका के बौद्ध इतिहास का पालि इतिवृत्त है, जो अशोक के धर्म-प्रचार अभियानों का स्रोत है। युग्म 3 गलत है: बृहदारण्यक सबसे पुराने उपनिषदों में से एक है। युग्म 4 गलत है: भद्रबाहु का माना जाने वाला कल्पसूत्र तीर्थंकरों के जीवन वाला एक जैन ग्रंथ है; इसे कर्मकांड पर वैदिक कल्पसूत्रों से भ्रमित नहीं करना चाहिए।','ancient-texts-religions-pairs','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson); R.S. Sharma, India''s Ancient Past (Oxford University Press).','draft'),
('upsc','History','Ancient','match_the_following','medium','Consider the following pairs of Vedic terms and their meanings:','वैदिक शब्दों और उनके अर्थों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Bali", "2. Vidatha", "3. Gavishti", "4. Bhagadugha"], "list_1_hi": ["1. बलि", "2. विदथ", "3. गविष्टि", "4. भागदुघ"], "list_2": ["An offering or tribute given to the chief", "A tribal assembly", "War, literally ''the search for cows''", "The collector of the king''s share"], "list_2_hi": ["सरदार को दी जाने वाली भेंट या कर", "एक कबीलाई सभा", "युद्ध, शाब्दिक अर्थ ''गायों की खोज''", "राजा का भाग वसूलने वाला अधिकारी"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. In the Rig Vedic period, bali was a voluntary offering to the chief that later hardened into a tax; the vidatha was among the oldest assemblies, in which women also took part; gavishti shows how central cattle were; and in later Vedic texts the bhagadugha appears among the ratnins, the king''s high officials, collecting his share of produce. A student who expects at least one mismatch will fall for ''Only three pairs''.','चारों युग्म सही हैं। ऋग्वैदिक काल में बलि सरदार को दी जाने वाली स्वैच्छिक भेंट थी, जो बाद में कर बन गई; विदथ सबसे पुरानी सभाओं में था, जिसमें स्त्रियाँ भी भाग लेती थीं; गविष्टि दिखाता है कि मवेशी कितने केंद्रीय थे; और उत्तर वैदिक ग्रंथों में भागदुघ रत्नियों, यानी राजा के उच्च अधिकारियों, में आता है, जो उपज में उसका भाग वसूलता था। जो विद्यार्थी कम से कम एक बेमेल की अपेक्षा करता है, वह ''केवल तीन युग्म'' के जाल में फँसेगा।','ancient-vedic-terms-pairs','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press), chapters on the Vedic age.','draft'),
('upsc','History','Ancient','match_the_following','medium','Consider the following pairs of ancient centres of learning and the present-day States in which they lay:','प्राचीन शिक्षा-केंद्रों और आज के उन राज्यों के निम्नलिखित युग्मों पर विचार कीजिए जिनमें वे स्थित थे:','{"list_1": ["1. Nalanda", "2. Vikramashila", "3. Valabhi", "4. Odantapuri"], "list_1_hi": ["1. नालंदा", "2. विक्रमशिला", "3. वलभी", "4. ओदंतपुरी"], "list_2": ["Bihar", "West Bengal", "Gujarat", "Odisha"], "list_2_hi": ["बिहार", "पश्चिम बंगाल", "गुजरात", "ओडिशा"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 3 are correct. Nalanda lies near Rajgir in Bihar, and Valabhi, the capital of the Maitrakas in Saurashtra, was a great centre of learning visited by I-tsing. Pair 2 is wrong: Vikramashila, founded by the Pala king Dharmapala, lies at Antichak in Bhagalpur district of Bihar, though the Palas ruled from Bengal. Pair 4 is wrong: Odantapuri was at present-day Bihar Sharif, also in Bihar; the name is sometimes confused with Odisha (Odra).','केवल युग्म 1 और 3 सही हैं। नालंदा बिहार में राजगीर के पास है, और सौराष्ट्र में मैत्रकों की राजधानी वलभी शिक्षा का बड़ा केंद्र था, जहाँ इत्सिंग भी गया। युग्म 2 गलत है: पाल राजा धर्मपाल द्वारा स्थापित विक्रमशिला बिहार के भागलपुर ज़िले के अंतीचक में है, हालाँकि पाल बंगाल से शासन करते थे। युग्म 4 गलत है: ओदंतपुरी वर्तमान बिहार शरीफ़ में, यानी बिहार में ही, था; इसके नाम को कभी-कभी ओडिशा (ओड्र) से भ्रमित कर दिया जाता है।','ancient-learning-centres-states-pairs','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapter 10; Archaeological Survey of India -- Vikramashila.','draft'),
('upsc','History','Ancient','match_the_following','easy','Consider the following pairs of Vedas and their contents:','वेदों और उनकी विषय-वस्तु के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Sama Veda", "2. Yajur Veda", "3. Atharva Veda", "4. Rig Veda"], "list_1_hi": ["1. सामवेद", "2. यजुर्वेद", "3. अथर्ववेद", "4. ऋग्वेद"], "list_2": ["Hymns set to melodies for chanting", "Formulas for sacrifices", "Charms and spells", "Hymns of praise to the gods"], "list_2_hi": ["गायन के लिए स्वरबद्ध मंत्र", "यज्ञों के सूत्र", "जादू-टोने और मंत्र", "देवताओं की स्तुति के सूक्त"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. The Rig Veda is the oldest collection of hymns; the Sama Veda sets many of them to melodies and is seen as a source of Indian music; the Yajur Veda gives the formulas recited by priests at sacrifices; and the Atharva Veda contains charms against disease and misfortune, giving a glimpse of popular beliefs.','चारों युग्म सही हैं। ऋग्वेद सूक्तों का सबसे पुराना संग्रह है; सामवेद उनमें से कई को स्वरों में बाँधता है और भारतीय संगीत का स्रोत माना जाता है; यजुर्वेद यज्ञों में पुरोहितों द्वारा पढ़े जाने वाले सूत्र देता है; और अथर्ववेद में रोग और दुर्भाग्य से बचाव के मंत्र हैं, जो लोक-विश्वासों की झलक देते हैं।','ancient-vedas-contents-pairs','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press); NCERT Class VI, Our Pasts I -- What Books and Burials Tell Us.','draft'),
('upsc','History','Ancient','match_the_following','easy','Consider the following pairs of ancient names and the present-day places they are identified with:','प्राचीन नामों और आज के उन स्थानों के निम्नलिखित युग्मों पर विचार कीजिए जिनसे उनकी पहचान की जाती है:','{"list_1": ["1. Pataliputra", "2. Pratishthana", "3. Purushapura", "4. Ujjayini"], "list_1_hi": ["1. पाटलिपुत्र", "2. प्रतिष्ठान", "3. पुरुषपुर", "4. उज्जयिनी"], "list_2": ["Patna", "Pune", "Peshawar", "Indore"], "list_2_hi": ["पटना", "पुणे", "पेशावर", "इंदौर"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Only pairs 1 and 3 are correct. Pataliputra, capital of the Mauryas and the Guptas, lies under modern Patna, and Purushapura was the Kushana capital at present-day Peshawar. Pair 2 is wrong: Pratishthana, the Satavahana capital, is Paithan on the Godavari in Aurangabad district, Maharashtra. Pair 4 is wrong: Ujjayini is Ujjain, on the Shipra, the capital of Avanti.','केवल युग्म 1 और 3 सही हैं। मौर्यों और गुप्तों की राजधानी पाटलिपुत्र आधुनिक पटना के नीचे है, और पुरुषपुर वर्तमान पेशावर में कुषाण राजधानी थी। युग्म 2 गलत है: सातवाहनों की राजधानी प्रतिष्ठान महाराष्ट्र के औरंगाबाद ज़िले में गोदावरी पर पैठण है। युग्म 4 गलत है: उज्जयिनी शिप्रा पर उज्जैन है, जो अवंति की राजधानी थी।','ancient-ancient-modern-names-pairs','original_pattern_matched','R.S. Sharma, India''s Ancient Past (Oxford University Press); Upinder Singh, A History of Ancient and Early Medieval India (Pearson) (maps).','draft'),
('upsc','History','Ancient','match_the_following','easy','Consider the following pairs of dynasties and the regions they ruled:','राजवंशों और उनके शासित क्षेत्रों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. Satavahanas", "2. Vakatakas", "3. Kadambas", "4. Western Gangas"], "list_1_hi": ["1. सातवाहन", "2. वाकाटक", "3. कदंब", "4. पश्चिमी गंग"], "list_2": ["Deccan", "Vidarbha and the northern Deccan", "Banavasi in Karnataka", "Bengal"], "list_2_hi": ["दक्कन", "विदर्भ और उत्तरी दक्कन", "कर्नाटक में बनवासी", "बंगाल"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb,2,0.66,'Three pairs are correct. The Satavahanas ruled the Deccan; the Vakatakas, allied by marriage to the Guptas through Prabhavatigupta, ruled Vidarbha and patronised some of the Ajanta caves; and the Kadambas, founded by Mayurasharman, ruled from Banavasi in north Karnataka. Pair 4 is wrong: the Western Gangas ruled southern Karnataka from Talakad; the Eastern Gangas ruled Kalinga (Odisha) -- neither ruled Bengal, and the shared name ''Ganga'' is the trap.','तीन युग्म सही हैं। सातवाहनों ने दक्कन पर शासन किया; प्रभावतीगुप्ता के ज़रिए गुप्तों से वैवाहिक संबंध वाले वाकाटकों ने विदर्भ पर शासन किया और अजंता की कुछ गुफाओं को संरक्षण दिया; और मयूरशर्मन द्वारा स्थापित कदंबों ने उत्तरी कर्नाटक के बनवासी से शासन किया। युग्म 4 गलत है: पश्चिमी गंगों ने तलकाड से दक्षिणी कर्नाटक पर शासन किया; पूर्वी गंगों ने कलिंग (ओडिशा) पर; दोनों में से किसी ने बंगाल पर शासन नहीं किया, और साझा नाम ''गंगा'' ही जाल है।','ancient-dynasties-regions-pairs','original_pattern_matched','Upinder Singh, A History of Ancient and Early Medieval India (Pearson), chapters 9 and 10.','draft')
